const fs = require('fs');

function extractMemoryValues(filePath) {
    const buffer = fs.readFileSync(filePath);
    const memory = {};

    // Parse ELF header
    const e_entry = buffer.readUInt32LE(0x18) | (buffer.readUInt32LE(0x1c) << 32);
    const e_phoff = buffer.readUInt32LE(0x20) | (buffer.readUInt32LE(0x24) << 32);
    const e_shoff = buffer.readUInt32LE(0x28) | (buffer.readUInt32LE(0x2c) << 32);
    const e_phentsize = buffer.readUInt16LE(0x36);
    const e_phnum = buffer.readUInt16LE(0x38);
    const e_shentsize = buffer.readUInt16LE(0x3a);
    const e_shnum = buffer.readUInt16LE(0x3c);
    const e_shstrndx = buffer.readUInt16LE(0x3e);

    // Parse section headers
    const sections = [];
    for (let i = 0; i < e_shnum; i++) {
        const offset = e_shoff + i * e_shentsize;
        const sh_name = buffer.readUInt32LE(offset);
        const sh_type = buffer.readUInt32LE(offset + 4);
        const sh_flags = buffer.readUInt64LE ? buffer.readUInt64LE(offset + 8) : 
                         (buffer.readUInt32LE(offset + 12) << 32 | buffer.readUInt32LE(offset + 8));
        const sh_addr = buffer.readUInt64LE ? buffer.readUInt64LE(offset + 16) : 
                        (buffer.readUInt32LE(offset + 20) << 32 | buffer.readUInt32LE(offset + 16));
        const sh_offset = buffer.readUInt64LE ? buffer.readUInt64LE(offset + 24) : 
                          (buffer.readUInt32LE(offset + 28) << 32 | buffer.readUInt32LE(offset + 24));
        const sh_size = buffer.readUInt64LE ? buffer.readUInt64LE(offset + 32) : 
                        (buffer.readUInt32LE(offset + 36) << 32 | buffer.readUInt32LE(offset + 32));
        const sh_link = buffer.readUInt32LE(offset + 40);
        const sh_info = buffer.readUInt32LE(offset + 44);
        const sh_addralign = buffer.readUInt64LE ? buffer.readUInt64LE(offset + 48) : 
                             (buffer.readUInt32LE(offset + 52) << 32 | buffer.readUInt32LE(offset + 48));
        const sh_entsize = buffer.readUInt64LE ? buffer.readUInt64LE(offset + 56) : 
                           (buffer.readUInt32LE(offset + 60) << 32 | buffer.readUInt32LE(offset + 56));

        sections.push({
            name: sh_name,
            type: sh_type,
            addr: sh_addr,
            offset: sh_offset,
            size: sh_size,
            link: sh_link
        });
    }

    // Get section name string table
    const shstrtab = sections[e_shstrndx];
    const sectionNames = [];
    let nameOffset = shstrtab.offset;
    let currentName = "";
    for (let i = 0; i < buffer.length; i++) {
        if (i >= shstrtab.offset && i < shstrtab.offset + shstrtab.size) {
            if (buffer[i] === 0) {
                sectionNames.push(currentName);
                currentName = "";
            } else {
                currentName += String.fromCharCode(buffer[i]);
            }
        }
    }

    // Assign names to sections
    for (let i = 0; i < sections.length; i++) {
        sections[i].name = sectionNames[sections[i].name] || "";
    }

    // Helper to read 64-bit value from buffer
    function readUInt64LE(buf, offset) {
        const low = buf.readUInt32LE(offset);
        const high = buf.readUInt32LE(offset + 4);
        return high * 2**32 + low;
    }

    // Helper to read 32-bit value from buffer
    function readUInt32LE(buf, offset) {
        return buf.readUInt32LE(offset);
    }

    // Extract values from sections that contain data
    function extractSectionValues(section, addressSize = 64) {
        if (section.size === 0) return;

        const addr = section.addr;
        const offset = section.offset;
        const size = section.size;

        if (addressSize === 64) {
            for (let i = 0; i + 8 <= size; i += 8) {
                const value = readUInt64LE(buffer, offset + i);
                const address = addr + i;
                if (address > 0) {
                    memory[address.toString()] = value;
                }
            }
        } else {
            for (let i = 0; i + 4 <= size; i += 4) {
                const value = readUInt32LE(buffer, offset + i);
                const address = addr + i;
                if (address > 0) {
                    memory[address.toString()] = value;
                }
            }
        }
    }

    // Extract from data-containing sections
    for (const section of sections) {
        // Extract from sections with data (PROGBITS type = 1)
        if (section.type === 1 && section.size > 0) {
            // For sections with 8-byte alignment, extract 64-bit values
            if (section.addr % 8 === 0 || section.name === '.dynamic' || 
                section.name === '.got' || section.name === '.init_array' || 
                section.name === '.fini_array' || section.name === '.dynsym') {
                extractSectionValues(section, 64);
            } else {
                // For other sections, extract 8-bit bytes
                for (let i = 0; i < section.size; i++) {
                    const value = buffer[section.offset + i];
                    const address = section.addr + i;
                    if (address > 0) {
                        memory[address.toString()] = value;
                    }
                }
            }
        }
    }

    // Also extract raw bytes from the entire file at their file offsets
    // (treating file offset as address for raw binary data)
    for (let i = 0; i < buffer.length; i += 8) {
        if (i + 8 <= buffer.length) {
            const value = readUInt64LE(buffer, i);
            // Only include addresses that correspond to actual section data
            const inSection = sections.some(s => i >= s.offset && i < s.offset + s.size);
            if (inSection) {
                const addrStr = i.toString();
                if (!(addrStr in memory)) {
                    memory[addrStr] = value;
                }
            }
        }
    }

    return memory;
}

// Main execution
const filePath = process.argv[2];
if (!filePath) {
    console.error("Usage: node extract.js <binary_file>");
    process.exit(1);
}

const memory = extractMemoryValues(filePath);
console.log(JSON.stringify(memory));

