        if (littleEndian) {
            return buffer.readUInt32LE(offset) + buffer.readUInt32LE(offset + 4) * 2**32;
        } else {
            return buffer.readUInt32BE(offset) * 2**32 + buffer.readUInt32BE(offset + 4);
        }
    }

    function readUInt32(offset) {
        if (littleEndian) {
            return buffer.readUInt32LE(offset);
        } else {
            return buffer.readUInt32BE(offset);
        }
    }

    function readUInt16(offset) {
        if (littleEndian) {
            return buffer.readUInt16LE(offset);
        } else {
            return buffer.readUInt16BE(offset);
        }
    }

    const e_phoff = is64bit ? readUInt64(0x20) : readUInt32(0x1c);
    const e_shoff = is64bit ? readUInt64(0x28) : readUInt32(0x24);
    const e_phentsize = readUInt16(0x36);
    const e_phnum = readUInt16(0x38);
    const e_shentsize = readUInt16(0x3a);
    const e_shnum = readUInt16(0x3c);
    const e_shstrndx = readUInt16(0x3e);

    // Parse section headers
    const sections = [];
    for (let i = 0; i < e_shnum; i++) {
        const offset = e_shoff + i * e_shentsize;
        const sh_name = readUInt32(offset);
        const sh_type = readUInt32(offset + 4);
        const sh_flags = is64bit ? readUInt64(offset + 8) : readUInt64(offset + 8);
        const sh_addr = is64bit ? readUInt64(offset + 16) : readUInt64(offset + 16);
        const sh_offset = is64bit ? readUInt64(offset + 24) : readUInt64(offset + 24);
        const sh_size = is64bit ? readUInt64(offset + 32) : readUInt64(offset + 32);
        const sh_link = readUInt32(offset + 40);
        const sh_info = readUInt32(offset + 44);
        const sh_addralign = is64bit ? readUInt64(offset + 48) : readUInt64(offset + 48);
        const sh_entsize = is64bit ? readUInt64(offset + 56) : readUInt64(offset + 56);

        sections.push({
            nameIdx: sh_name,
            type: sh_type,
            addr: sh_addr,
            offset: sh_offset,
            size: sh_size,
            link: sh_link
        });
    }

