    function readUInt64LEFromFile(buf, offset) {
        const low = buf.readUInt32LE(offset);
        const high = buf.readUInt32LE(offset + 4);
        return high * 2**32 + low;
    }

    // Helper to read 32-bit value from buffer at file offset
    function readUInt32LEFromFile(buf, offset) {
        return buf.readUInt32LE(offset);
    }

