    // We extract 64-bit values from sections with 8-byte alignment
    for (const section of sections) {
        if (section.size === 0 || section.addr === 0) continue;

        // Determine alignment based on section type
        let align = section.sh_addralign || 8;
        if (align === 0) align = 1;

        // For data sections, extract 64-bit values
        const dataSections = ['.data', '.bss', '.got', '.plt', '.init_array', '.fini_array', '.dynamic', '.dynsym', '.dynstr', '.symtab', '.strtab', '.rela.dyn', '.rela.plt', '.gnu.hash', '.gnu.version', '.gnu.version_r', '.note.gnu.property', '.note.gnu.build-id', '.note.ABI-tag', '.eh_frame', '.eh_frame_hdr'];

        const isDataSection = dataSections.includes(section.name) || section.type === 1; // SHT_PROGBITS

        if (isDataSection && section.name !== '.text' && section.name !== '.init' && section.name !== '.fini' && section.name !== '.plt' && section.name !== '.plt.got' && section.name !== '.plt.sec') {
            // Extract 64-bit values
            for (let i = 0; i + 8 <= section.size; i += 8) {
                const value = readUInt64LEFromFile(buffer, section.offset + i);
                const address = section.addr + i;
                if (address > 0) {
                    memory[address.toString()] = value;
                }
            }
            // Handle remaining bytes if any
            if (section.size % 8 !== 0) {
                for (let i = Math.floor(section.size / 8) * 8; i < section.size; i++) {
