            // For code sections and others, extract bytes
            for (let i = 0; i < section.size; i++) {
                const value = buffer[section.offset + i];
                const address = section.addr + i;
                if (address > 0) {
                    memory[address.toString()] = value;
                }
            }
        }
    }

    return memory;
}

