const fs = require('fs');

function extractMemoryValues(filePath) {
    const buffer = fs.readFileSync(filePath);
    const memory = {};

    // Extract all 32-bit values from the binary file
    // Using file offset as the memory address (with base 0x400000 for typical x86-64 layout)
    const baseAddress = 0x400000;

    for (let i = 0; i + 4 <= buffer.length; i += 4) {
        const value = buffer.readUInt32LE(i);
        const address = baseAddress + i;
        memory[address.toString()] = value;
    }

    // Handle remaining bytes (less than 4 bytes at the end)
    const remainingStart = Math.floor(buffer.length / 4) * 4;
    for (let i = remainingStart; i < buffer.length; i++) {
        const value = buffer[i];
        const address = baseAddress + i;
        memory[address.toString()] = value;
    }

    return memory;
}

